"const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..', '..', '..', 'scratch', 'bt360mak');
const frontendDir = path.join(root, 'frontend');
const gasDir = path.join(root, 'gas');

let html = fs.readFileSync(path.join(frontendDir, 'index.html'), 'utf8');
const themesCss = fs.readFileSync(path.join(frontendDir, 'css', 'themes.css'), 'utf8');
const mainCss = fs.readFileSync(path.join(frontendDir, 'css', 'main.css'), 'utf8');
const btData = fs.readFileSync(path.join(frontendDir, 'js', 'battrickData.js'), 'utf8');
const apiJs = fs.readFileSync(path.join(frontendDir, 'js', 'api.js'), 'utf8');
const chartsJs = fs.readFileSync(path.join(frontendDir, 'js', 'charts.js'), 'utf8');
const appJs = fs.readFileSync(path.join(frontendDir, 'js', 'app.js'), 'utf8');

// Replace stylesheet links with inline style tags
const styleBundle = `
  <style>
${themesCss}
${mainCss}
  </style>
`;
html = html.replace(/<link rel="stylesheet" href="css\/themes\.css">\s*<link rel="stylesheet" href="css\/main\.css">/, styleBundle);

// Replace script tags with inline scripts
const scriptBundle = `
  <script>
${btData}
${apiJs}
${chartsJs}
${appJs}
  </script>
`;
html = html.replace(/<script src="js\/battrickData\.js"><\/script>\s*<script src="js\/api\.js"><\/script>\s*<script src="js\/charts\.js"><\/script>\s*<script src="js\/app\.js"><\/script>/, scriptBundle);

fs.writeFileSync(path.join(gasDir, 'index.html'), html);
console.log('Successfully generated gas/index.html');
"

