"/**
 * BT360MAK - Sovereign Turf & Gold Signature Design System
 * 100% Custom CSS - Lively, Animated, Colorful & Responsive
 * Primary Typography: Plus Jakarta Sans | Numbers & IDs: JetBrains Mono
 */

:root {
  /* Signature Theme: Sovereign Turf & Gold */
  --bg-primary: #05100c;
  --bg-secondary: #091a14;
  --bg-card: rgba(13, 34, 28, 0.78);
  --bg-card-hover: rgba(18, 48, 39, 0.92);
  --bg-surface: #0f2b23;
  --bg-glass: rgba(15, 43, 35, 0.65);

  --text-main: #f0fdf4;
  --text-muted: #86efac;
  --text-sub: #a7f3d0;
  --text-dim: #6ee7b7;

  /* Luminous Cricket Palette */
  --emerald: #10b981;
  --emerald-bright: #34d399;
  --emerald-dark: #064e3b;
  --emerald-glow: rgba(16, 185, 129, 0.35);

  --gold: #f59e0b;
  --gold-bright: #fbbf24;
  --gold-glow: rgba(245, 158, 11, 0.35);

  --crimson: #f43f5e;
  --crimson-glow: rgba(244, 63, 94, 0.35);

  --cyan: #06b6d4;
  --cyan-bright: #38bdf8;
  --cyan-glow: rgba(6, 182, 212, 0.3);

  --purple: #8b5cf6;

  --border-color: rgba(26, 77, 68, 0.6);
  --border-highlight: rgba(52, 211, 153, 0.5);
  --border-gold: rgba(245, 158, 11, 0.4);

  --card-shadow: 0 10px 30px -5px rgba(0, 0, 0, 0.5), 0 0 20px -5px var(--emerald-glow);
  --glow-shadow: 0 0 25px rgba(16, 185, 129, 0.25);

  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  overflow-x: hidden;
  line-height: 1.5;
  background-image: 
    radial-gradient(circle at 15% 15%, rgba(16, 185, 129, 0.08) 0%, transparent 40%),
    radial-gradient(circle at 85% 85%, rgba(245, 158, 11, 0.06) 0%, transparent 40%),
    radial-gradient(circle at 50% 50%, rgba(6, 78, 59, 0.05) 0%, transparent 60%);
  background-attachment: fixed;
}

