"/**
 * BT360MAK - themes.css
 * Sovereign Edition Accent & Visual Embellishments Module
 */

/* Shimmer Glow Animation */
@keyframes goldShimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

.text-gold-shimmer {
  background: linear-gradient(90deg, #f59e0b 0%, #fef08a 50%, #f59e0b 100%);
  background-size: 200% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: goldShimmer 3s linear infinite;
}

/* Neon Pulse Border */
.border-pulse-emerald {
  animation: borderGlow 2.5s infinite alternate;
}

@keyframes borderGlow {
  0% { border-color: rgba(16, 185, 129, 0.3); box-shadow: 0 0 10px rgba(16, 185, 129, 0.2); }
  100% { border-color: rgba(52, 211, 153, 0.8); box-shadow: 0 0 25px rgba(16, 185, 129, 0.4); }
}

/* Radar ping */
.radar-ping {
  position: relative;
  display: inline-block;
}

.radar-ping::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  border: 1px solid var(--emerald-bright);
  animation: radarWave 2s cubic-bezier(0, 0.2, 0.8, 1) infinite;
}

@keyframes radarWave {
  0% { width: 0; height: 0; opacity: 1; }
  100% { width: 35px; height: 35px; opacity: 0; }
}
